[{"order":1,"type":"heading","text":"Fullscreen API: Requesting and Handling Fullscreen Mode"},{"order":2,"type":"paragraph","text":"The Fullscreen API in HTML5 provides a standardized way to display a web page or a specific element in full-screen mode. This tutorial will guide you through requesting and handling fullscreen mode using JavaScript."},{"order":3,"type":"subheading","text":"Understanding the Fullscreen API"},{"order":4,"type":"paragraph","text":"The Fullscreen API allows web applications to take over the entire screen, hiding browser UI elements like the address bar and tabs. This is particularly useful for games, video players, and presentations."},{"order":5,"type":"subheading","text":"Requesting Fullscreen Mode"},{"order":6,"type":"paragraph","text":"To request fullscreen mode, you'll need to call the `requestFullscreen()` method on the element you want to display in fullscreen. Different browsers use different prefixes, so you'll need to handle these variations."},{"order":7,"type":"code","text":"function requestFullscreen(element) {
  if (element.requestFullscreen) {
    element.requestFullscreen();
  } else if (element.mozRequestFullScreen) { /* Firefox */
    element.mozRequestFullScreen();
  } else if (element.webkitRequestFullscreen) { /* Chrome, Safari & Opera */
    element.webkitRequestFullscreen();
  } else if (element.msRequestFullscreen) { /* IE/Edge */
    element.msRequestFullscreen();
  }
}"},{"order":8,"type":"paragraph","text":"Here's how you might use this function with a button click:"},{"order":9,"type":"code","text":"<button id="fullscreenButton">Go Fullscreen</button>
<div id="fullscreenElement">This is the element to fullscreen.</div>

<script>
  const button = document.getElementById('fullscreenButton');
  const element = document.getElementById('fullscreenElement');

  button.addEventListener('click', () => {
    requestFullscreen(element);
  });
</script>"},{"order":10,"type":"subheading","text":"Exiting Fullscreen Mode"},{"order":11,"type":"paragraph","text":"To exit fullscreen mode, you'll use the `exitFullscreen()` method on the `document` object. Again, you'll need to handle browser prefixes."},{"order":12,"type":"code","text":"function exitFullscreen() {
  if (document.exitFullscreen) {
    document.exitFullscreen();
  } else if (document.mozCancelFullScreen) { /* Firefox */
    document.mozCancelFullScreen();
  } else if (document.webkitExitFullscreen) { /* Chrome, Safari and Opera */
    document.webkitExitFullscreen();
  } else if (document.msExitFullscreen) { /* IE/Edge */
    document.msExitFullscreen();
  }
}"},{"order":13,"type":"paragraph","text":"You can add a button to exit fullscreen:"},{"order":14,"type":"code","text":"<button id="exitFullscreenButton">Exit Fullscreen</button>

<script>
  const exitButton = document.getElementById('exitFullscreenButton');

  exitButton.addEventListener('click', () => {
    exitFullscreen();
  });
</script>"},{"order":15,"type":"subheading","text":"Detecting Fullscreen Mode Changes"},{"order":16,"type":"paragraph","text":"You can listen for events that indicate when the fullscreen state changes. This allows you to update your UI or perform other actions when entering or exiting fullscreen."},{"order":17,"type":"code","text":"document.addEventListener('fullscreenchange', () => {
  if (document.fullscreenElement) {
    console.log('Entered fullscreen mode.');
  } else {
    console.log('Exited fullscreen mode.');
  }
});

document.addEventListener('mozfullscreenchange', () => { // Firefox
  if (document.mozFullScreenElement) {
    console.log('Entered fullscreen mode (Firefox).');
  } else {
    console.log('Exited fullscreen mode (Firefox).');
  }
});

document.addEventListener('webkitfullscreenchange', () => { // Chrome, Safari, Opera
  if (document.webkitFullscreenElement) {
    console.log('Entered fullscreen mode (WebKit).');
  } else {
    console.log('Exited fullscreen mode (WebKit).');
  }
});

document.addEventListener('msfullscreenchange', () => { // IE/Edge
  if (document.msFullscreenElement) {
    console.log('Entered fullscreen mode (IE/Edge).');
  } else {
    console.log('Exited fullscreen mode (IE/Edge).');
  }
});"},{"order":18,"type":"subheading","text":"Fullscreen Element Property"},{"order":19,"type":"paragraph","text":"The `document.fullscreenElement` property (and its prefixed versions) indicates the element that is currently in fullscreen mode, or `null` if no element is in fullscreen. This is useful for determining the current fullscreen state."},{"order":20,"type":"code","text":"const fullscreenElement = document.fullscreenElement || document.mozFullScreenElement || document.webkitFullscreenElement || document.msFullscreenElement;"},{"order":21,"type":"subheading","text":"Complete Example"},{"order":22,"type":"code","text":"<!DOCTYPE html>
<html>
<head>
  <title>Fullscreen API Example</title>
  <style>
    #fullscreenElement {
      width: 300px;
      height: 200px;
      background-color: lightblue;
      border: 1px solid black;
      padding: 20px;
    }
  </style>
</head>
<body>

  <button id="fullscreenButton">Go Fullscreen</button>
  <button id="exitFullscreenButton">Exit Fullscreen</button>
  <div id="fullscreenElement">This is the element to fullscreen.</div>

  <script>
    const button = document.getElementById('fullscreenButton');
    const exitButton = document.getElementById('exitFullscreenButton');
    const element = document.getElementById('fullscreenElement');

    function requestFullscreen(element) {
      if (element.requestFullscreen) {
        element.requestFullscreen();
      } else if (element.mozRequestFullScreen) { /* Firefox */
        element.mozRequestFullScreen();
      } else if (element.webkitRequestFullscreen) { /* Chrome, Safari & Opera */
        element.webkitRequestFullscreen();
      } else if (element.msRequestFullscreen) { /* IE/Edge */
        element.msRequestFullscreen();
      }
    }

    function exitFullscreen() {
      if (document.exitFullscreen) {
        document.exitFullscreen();
      } else if (document.mozCancelFullScreen) { /* Firefox */
        document.mozCancelFullScreen();
      } else if (document.webkitExitFullscreen) { /* Chrome, Safari and Opera */
        document.webkitExitFullscreen();
      } else if (document.msExitFullscreen) { /* IE/Edge */
        document.msExitFullscreen();
      }
    }

    button.addEventListener('click', () => {
      requestFullscreen(element);
    });

    exitButton.addEventListener('click', () => {
      exitFullscreen();
    });

    document.addEventListener('fullscreenchange', () => {
      if (document.fullscreenElement) {
        console.log('Entered fullscreen mode.');
      } else {
        console.log('Exited fullscreen mode.');
      }
    });

    document.addEventListener('mozfullscreenchange', () => { // Firefox
      if (document.mozFullScreenElement) {
        console.log('Entered fullscreen mode (Firefox).');
      } else {
        console.log('Exited fullscreen mode (Firefox).');
      }
    });

    document.addEventListener('webkitfullscreenchange', () => { // Chrome, Safari, Opera
      if (document.webkitFullscreenElement) {
        console.log('Entered fullscreen mode (WebKit).');
      } else {
        console.log('Exited fullscreen mode (WebKit).');
      }
    });

    document.addEventListener('msfullscreenchange', () => { // IE/Edge
      if (document.msFullscreenElement) {
        console.log('Entered fullscreen mode (IE/Edge).');
      } else {
        console.log('Exited fullscreen mode (IE/Edge).');
      }
    });

  </script>

</body>
</html>"},{"order":23,"type":"subheading","text":"Considerations"},{"order":24,"type":"bullet_point","text":"User Permission: Browsers typically require user interaction (e.g., a button click) to initiate fullscreen mode for security reasons."},{"order":25,"type":"bullet_point","text":"Browser Prefixes: Remember to include browser-specific prefixes for maximum compatibility, although modern browsers are increasingly adopting the unprefixed versions."},{"order":26,"type":"bullet_point","text":"Styling: When in fullscreen mode, you may need to adjust your CSS to ensure your content displays correctly on different screen sizes."},{"order":27,"type":"paragraph","text":"By following this tutorial, you should now have a solid understanding of how to request and handle fullscreen mode using the HTML5 Fullscreen API."}]
